		private class PendingDamage
		{
			public short index;

			public byte generation;

			public int damage;

			public bool phaseChange;

			public bool Matches(NPC n)
			{
				if (index == n.whoAmI)
				{
					return generation == n.generation;
				}
				return false;
			}
		}

		public struct DOTTally
		{
			public NPC npc;

			public int LifeRegenLoss;

			public int LifeRegenLossThatCanBeBoosted;

			public int ExpectedDamagePerSecond;

			public bool BlockNaturalRegeneration;

			public int SuperNaturalLifeRegen;

			public static DOTTally None => default(DOTTally);

			public void AddSuperNaturalRegeneration(int amount)
			{
				SuperNaturalLifeRegen += amount;
			}

			public void Add(int regenLoss, int expectedAmountPerSecond = 0)
			{
				BlockNaturalRegeneration = true;
				LifeRegenLoss += regenLoss;
				if (ExpectedDamagePerSecond < expectedAmountPerSecond)
				{
					ExpectedDamagePerSecond = expectedAmountPerSecond;
				}
			}

			public void AddPoison(int regenLoss, int expectedAmountPerSecond = 0)
			{
				SupportAcceleration(regenLoss);
				Add(regenLoss, expectedAmountPerSecond);
			}

			public void AddBloodLoss(int regenLoss, int expectedAmountPerSecond = 0)
			{
				SupportAcceleration(regenLoss);
				Add(regenLoss, expectedAmountPerSecond);
			}

			public void AddFlamable(int regenLoss, int expectedAmountPerSecond = 0)
			{
				if (npc.drippingSlime)
				{
					regenLoss *= 2;
				}
				if (npc.type == 1 && npc.ai[1] == 9f)
				{
					regenLoss += 16;
				}
				SupportAcceleration(regenLoss);
				Add(regenLoss, expectedAmountPerSecond);
			}

			public void AddStackedProjecitle(short projTypeToLookFor, int damagePerSecond, int expectedDamagePerSecondDivider)
			{
				int whoAmI = npc.whoAmI;
				int num = 0;
				for (int i = 0; i < 1000; i++)
				{
					if (Main.projectile[i].active && Main.projectile[i].type == projTypeToLookFor && Main.projectile[i].ai[0] == 1f && Main.projectile[i].ai[1] == (float)whoAmI)
					{
						num++;
					}
				}
				if (num == 0)
				{
					num = 1;
				}
				int expectedAmountPerSecond = num * damagePerSecond / expectedDamagePerSecondDivider;
				Add(num * 2 * damagePerSecond, expectedAmountPerSecond);
			}

			private void SupportAcceleration(int regenLoss)
			{
				if (npc.acceleratePoisons)
				{
					LifeRegenLossThatCanBeBoosted += regenLoss;
				}
			}
		}

