		public static bool SpawnAllowed_Merchant()
		{
			if (unlockedMerchantSpawn)
			{
				return true;
			}
			double num = 5000.0;
			int num2 = 0;
			for (int i = 0; i < 255; i++)
			{
				Player player = Main.player[i];
				if (!player.active)
				{
					continue;
				}
				for (int j = 0; j < 58; j++)
				{
					Item item = player.inventory[j];
					if (item != null && item.stack > 0)
					{
						if (item.type == 71)
						{
							num2 += item.stack;
						}
						if (item.type == 72)
						{
							num2 += item.stack * 100;
						}
						if (item.type == 73)
						{
							num2 += item.stack * 10000;
						}
						if (item.type == 74)
						{
							num2 += item.stack * 1000000;
						}
						if ((double)num2 >= num)
						{
							return true;
						}
					}
				}
			}
			return false;
		}

