		public void GetLifeStats(out int statLife, out int statLifeMax)
		{
			statLife = life;
			statLifeMax = lifeMax;
			if (realLife != -1)
			{
				statLife = Main.npc[realLife].life;
				statLifeMax = Main.npc[realLife].lifeMax;
			}
