		public void SetDefaults_ForNetId(int Type, NPCSpawnParams spawnparams, float scaleOverride)
		{
			SetDefaults(Type, spawnparams.WithScale(scaleOverride));
		}

		public NPC()
		{
			direction = 0;
			oldDirection = 0;
		}

		public static void ClearAll()
		{
			for (int i = 0; i < Main.maxNPCs; i++)
			{
				Main.npc[i] = new NPC
				{
					whoAmI = i
				};
				spawnSlotProtected[i] = 0;
				ResetNPCSlotData(i);
			}
			pendingDamages.Clear();
		}

		public static void ResetNPCSlotData(int npcIndex)
		{
			if (npcIndex < Main.maxNPCs)
			{
				PortalHelper.ResetNPCSlotData(npcIndex);
				Projectile.ResetNPCSlotData(npcIndex);
				Player.ResetNPCSlotData(npcIndex);
				if (Main.wofNPCIndex == npcIndex)
				{
					Main.wofNPCIndex = -1;
				}
				if (golemBoss == npcIndex)
				{
					golemBoss = -1;
				}
				if (deerclopsBoss == npcIndex)
				{
					deerclopsBoss = -1;
				}
				if (plantBoss == npcIndex)
				{
					plantBoss = -1;
				}
				if (crimsonBoss == npcIndex)
				{
					crimsonBoss = -1;
				}
			}
		}

		public void OnSpawn(IEntitySource source)
		{
			if (type == 113)
			{
				Main.wofNPCIndex = whoAmI;
			}
			if (type == 245)
			{
				golemBoss = whoAmI;
			}
			if (type == 668)
			{
				deerclopsBoss = whoAmI;
			}
			if (type == 262)
			{
				plantBoss = whoAmI;
			}
			if (type == 266)
			{
				crimsonBoss = whoAmI;
			}
		}

		public void SetDefaults(int Type, NPCSpawnParams spawnparams = default(NPCSpawnParams))
		{
			if (Main.getGoodWorld && !IsABestiaryIconDummy && spawnparams.sizeScaleOverride.HasValue)
			{
				spawnparams.sizeScaleOverride = (spawnparams.sizeScaleOverride + spawnparams.sizeScaleOverride * spawnparams.sizeScaleOverride) / 2f;
			}
			if (Type < 0)
			{
				SetDefaultsFromNetId(Type, spawnparams);
				return;
			}
			waterMovementSpeed = (lavaMovementSpeed = 0.5f);
