			if (type == 266 || type == 267)
			{
				num *= (double)balance;
				for (float num2 = 1f; num2 < balance; num2 += 0.34f)
				{
					if ((double)knockBackResist < 0.1)
					{
						knockBackResist = 0f;
						break;
