		public static bool ShouldEmpressBeEnraged()
		{
			if (Main.remixWorld)
			{
				if (empressRageMode)
				{
					return true;
				}
				int num = -1;
				for (int i = 0; i < Main.maxNPCs; i++)
				{
					if (Main.npc[i].type == 636)
					{
						num = i;
						break;
					}
				}
				if (num >= 0 && (double)Main.npc[num].Center.Y < Main.worldSurface * 16.0)
				{
					empressRageMode = true;
					return true;
				}
				empressRageMode = false;
				return false;
			}
			return Main.dayTime;
		}

