					{
						timeLeft = activeTime;
					}
					flag2 = true;
					break;
				case 583:
				case 584:
				case 585:
					if (!Main.dayTime && ai[2] == 0f)
					{
						flag2 = true;
						timeLeft = activeTime;
					}
					break;
