		private void CheckActive_WormSegments()
		{
			if (aiStyle != 6)
			{
				return;
			}
			int num = (int)ai[0];
			while (num != whoAmI && num > 0 && num < Main.maxNPCs)
			{
				NPC nPC = Main.npc[num];
				if (nPC.active && nPC.aiStyle == 6)
				{
					nPC.active = false;
					if (Main.netMode == 2)
					{
						NetMessage.SendData(23, -1, -1, null, num);
					}
					num = (int)nPC.ai[0];
					continue;
				}
				break;
			}
		}

