		public Rectangle? TryGetAdjustedHitboxFromTransformation(int targetType)
		{
			if (!ContentSamples.NpcsByNetId.TryGetValue(targetType, out var nPC))
			{
				return null;
			}
			if (!Collision.TryChangingSizeFromBottomCenter(base.Hitbox, nPC.width, nPC.height, out var changedHitbox))
			{
				return null;
			}
			return changedHitbox;
		}

		public bool TryMoveToTransformableSpaceInto(int targetType)
		{
			Rectangle? rectangle = TryGetAdjustedHitboxFromTransformation(targetType);
			if (!rectangle.HasValue)
			{
				return false;
			}
			position = rectangle.Value.TopLeft();
			return true;
		}

		public void Transform(int newType, float ai0 = 0f, float ai1 = 0f, float ai2 = 0f, float ai3 = 0f, bool withReposition = true)
		{
			if (Main.netMode != 1)
			{
				bool num = value == 0f;
				int oldType = type;
				int num2 = life;
				int num3 = lifeMax;
				if (withReposition)
				{
					position.Y += height;
				}
				SetDefaults(newType);
				if (withReposition)
				{
					position.Y -= height;
				}
				TargetClosest();
				if (num)
				{
					value = 0f;
				}
