				if (extraValue >= 1000000)
				{
					num7 = 247;
					num8 *= 0.25f;
				}
				else if (extraValue >= 10000)
				{
					num7 = 246;
					num8 *= 0.5f;
				}
				else if (extraValue >= 100)
				{
					num7 = 245;
