		public void NetUpdateIgnoreSpamLimit()
		{
			int num = (boss ? netSpamTicksPerPacketForBosses : netSpamTicksPerPacket);
			if (!netUpdate || netSpam > num * netSpamPacketLimit)
			{
				netSpam -= num;
			}
			netUpdate = true;
		}

