				if (onFire2)
				{
					none.AddFlamable(48, 10);
				}
				if (venom)
				{
					none.AddPoison(60, 15);
				}
				if (potentAcid)
				{
					none.AddPoison(180, 60);
				}
				if (chlorophyteSpore)
				{
					none.AddPoison(180, 60);
				}
				if (shadowFlame)
				{
					none.AddFlamable(30, 5);
				}
				if (oiled && (onFire || onFire2 || onFire3 || onFrostBurn || onFrostBurn2 || shadowFlame))
				{
					none.Add(50, 10);
				}
				if (javelined)
				{
					none.AddStackedProjecitle(598, 3, 1);
				}
				if (tentacleSpiked)
				{
					none.AddStackedProjecitle(971, 3, 1);
				}
				if (markedByEelWhip)
				{
					none.Add(100, 50);
				}
				if (bloodButchered)
				{
					none.AddStackedProjecitle(975, 4, 1);
				}
				if (daybreak)
				{
					none.AddStackedProjecitle(636, 100, 4);
				}
				if (celled)
				{
					none.AddStackedProjecitle(614, 20, 1);
				}
				if (dryadBane)
				{
					int dryadsBaneDamagePerSecond = GetDryadsBaneDamagePerSecond();
					none.Add(dryadsBaneDamagePerSecond * 2, dryadsBaneDamagePerSecond / 3);
				}
				if (soulDrain && realLife == -1)
				{
					none.Add(50, 5);
				}
				if (type == 59 && ai[1] == 174f && lavaWet)
				{
					none.AddSuperNaturalRegeneration(32);
				}
				if (type == 1)
				{
					if (ai[1] == 29f)
					{
						none.AddSuperNaturalRegeneration(16);
					}
					else if (ai[1] == 364f || ai[1] == 1104f || ai[1] == 365f || ai[1] == 1105f || ai[1] == 366f || ai[1] == 1106f)
					{
						none.AddSuperNaturalRegeneration(24);
					}
				}
				if (none.BlockNaturalRegeneration && lifeRegen > 0)
				{
					lifeRegen = 0;
				}
				int num2 = none.LifeRegenLoss;
				if (acceleratePoisons)
				{
					int lifeRegenLossThatCanBeBoosted = none.LifeRegenLossThatCanBeBoosted;
					int num3 = none.LifeRegenLoss - lifeRegenLossThatCanBeBoosted;
					float num4 = 2f;
					num2 = num3 + (int)((float)lifeRegenLossThatCanBeBoosted * num4);
				}
				lifeRegen -= num2;
				lifeRegen += none.SuperNaturalLifeRegen;
				if (none.ExpectedDamagePerSecond != 0)
				{
					num = none.ExpectedDamagePerSecond;
				}
				lifeRegenCount += lifeRegen;
				if (num == -1)
				{
					int num5 = lifeRegenCount / -120;
					if (num5 > 1)
					{
						num = num5;
					}
				}
				while (lifeRegenCount >= 120)
				{
					lifeRegenCount -= 120;
					if (!immortal)
					{
						if (life < lifeMax)
						{
							life++;
						}
						if (life > lifeMax)
						{
							life = lifeMax;
						}
					}
				}
				if (num > 0)
				{
					while (lifeRegenCount <= -120 * num)
					{
						lifeRegenCount += 120 * num;
						GetHurtByDebuff(num);
					}
				}
				else
				{
					while (lifeRegenCount <= -120)
					{
						lifeRegenCount += 120;
						GetHurtByDebuff(1);
					}
				}
			}
			if (chlorophyteSpore && Main.rand.Next(60) == 0)
			{
				Rectangle rect = getRect();
				rect.Inflate(-2, -2);
				Vector2 positionInWorld = Main.rand.NextVector2FromRectangle(rect);
				Vector2 vector = velocity * 0.5f;
				if (vector.Length() > 5f)
				{
					vector = vector.SafeNormalize(Vector2.Zero) * 5f;
				}
				ParticleOrchestrator.RequestParticleSpawn(clientOnly: true, ParticleOrchestraType.SporeCloud, new ParticleOrchestraSettings
				{
					PositionInWorld = positionInWorld,
					MovementVector = vector
				});
			}
		}

