		private void ApplyEelWhipDoT()
		{
			float num = 60f;
			int num2 = 50;
			if ((float)(++electricEelCounter) < num)
			{
				return;
			}
			electricEelCounter = 0;
			SoundEngine.PlaySound(HitSound, base.Center);
