		private void UpdateNPC_CastLights()
		{
			if (type >= 0 && NPCID.Sets.IsGoldCritter[type])
			{
				position += netOffset;
				Color color = Lighting.GetColor((int)base.Center.X / 16, (int)base.Center.Y / 16);
				if (color.R > 20 || color.B > 20 || color.G > 20)
				{
					int num = color.R;
					if (color.G > num)
					{
						num = color.G;
					}
					if (color.B > num)
					{
						num = color.B;
